type Authenticator interface {
    Authenticate(ctx context.Context, req AuthRequest) (*Token, error)
    Refresh(ctx context.Context, token *Token) (*Token, error)
    Revoke(ctx context.Context, tokenID string) error
}

type TokenStore interface {
    Get(ctx context.Context, tokenID string) (*Token, error)
    Set(ctx context.Context, token *Token, ttl time.Duration) error
    Delete(ctx context.Context, tokenID string) error
}

type UserService struct {
    repo UserRepository
    log  Logger
}

func NewUserService(repo UserRepository, log Logger) *UserService {
    return &UserService{
        repo: repo,
        log:  log,
    }
}

type Handler interface {
    ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type UserHandler struct {
    service UserService
    logger  Logger
}

type HTTPError struct {
    Code    int    `json:"code"`
    Message string `json:"message"`
}

func (e *HTTPError) Error() string {
    return e.Message
}

func WriteError(w http.ResponseWriter, err error) {
    if httpErr, ok := err.(*HTTPError); ok {
        w.WriteHeader(httpErr.Code)
        json.NewEncoder(w).Encode(httpErr)
        return
    }
    w.WriteHeader(http.StatusInternalServerError)
    json.NewEncoder(w).Encode(HTTPError{
        Code:    500,
        Message: "Internal server error",
    })
}
